bool findShaderBlob(ApusrFramegenShaderEffect effect, std::uint8_t passId, std::uint32_t permutationOptions, ApusrFramegenShaderBlob* outBlob) noexcept {
    if (!outBlob) return false;
    std::uint16_t blobIndex = 0xffffu;
    if (effect == APUSR_FRAMEGEN_SHADER_EFFECT_FRAME_INTERPOLATION) {
        if (passId < 11u && permutationOptions < 32u) blobIndex = kFiBlobIndex[passId][permutationOptions];
    } else if (effect == APUSR_FRAMEGEN_SHADER_EFFECT_OPTICAL_FLOW) {
        if (passId < 7u && permutationOptions < 8u) blobIndex = kOfBlobIndex[passId][permutationOptions];
    }
    if (blobIndex == 0xffffu) { std::memset(outBlob, 0, sizeof(*outBlob)); return false; }
    const auto& blob = kBlobs[blobIndex];
    *outBlob = {blob.data, blob.size, blob.cbvCount, blob.srvTextureCount, blob.uavTextureCount, blob.srvBufferCount, blob.uavBufferCount, blob.cbvNames, blob.cbvBindings, blob.cbvCounts, blob.cbvSpaces, blob.srvTextureNames, blob.srvTextureBindings, blob.srvTextureCounts, blob.srvTextureSpaces, blob.uavTextureNames, blob.uavTextureBindings, blob.uavTextureCounts, blob.uavTextureSpaces, blob.srvBufferNames, blob.srvBufferBindings, blob.srvBufferCounts, blob.srvBufferSpaces, blob.uavBufferNames, blob.uavBufferBindings, blob.uavBufferCounts, blob.uavBufferSpaces, effect, passId, 0u, permutationOptions};
    return true;
}
